        for i in range(len(current_grid)):
            for j in range(len(current_grid[0])):
                # Check if the position is not occupied
                if current_grid[i][j] == 0:
                    # Check if the position satisfies the hint condition
                    if self.check_condition(i + 1, j + 1, operation, condition):
                        # Select the position as the next move
                        position_selected = (i + 1, j + 1)
                        break
            if position_selected is not None:
