        if operation =='sum':
            value = row + col
        elif operation == 'product':
            value = row * col
        elif operation == 'difference':
            value = abs(row - col)
        else:
            raise ValueError("Invalid operation")

        if condition.startswith('is less than'):
            v1 = int(condition.split()[-1])
            return value < v1
        elif condition.startswith('is greater than'):
            v1 = int(condition.split()[-1])
            return value > v1
        elif condition.startswith('contains digit'):
            v1 = int(condition.split()[-1])
            return str(v1) in str(value)
        elif condition.startswith('is even'):
            return value % 2 == 0
        elif condition.startswith('is odd'):
            return value % 2!= 0
        elif condition.startswith('is between'):
            v1, v2 = map(int, condition.split()[-3:])
            return v1 <= value <= v2
        else:
            raise ValueError("Invalid condition")

