                    valid_positions.append((row, col))

        # Select the position that is most likely to help us build a path
        if valid_positions:
            if player_idx == 1:  # Player 1: left to right
                position_selected = min(valid_positions, key=lambda x: x[1])
            else:  # Player 2: top to bottom
                position_selected = min(valid_positions, key=lambda x: x[0])

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )
